/** @typedef {'none' | 'width' | 'height' | 'both'} FitMode */
/** @typedef {'manual' | 'fit-width' | 'fit-height' | 'fit-page'} DefaultZoomMode */

/**
 * Convert the public PageEditor preference into the resizer's internal fit state.
 * `manual` deliberately maps to `none`: callers retain the existing numeric
 * `defaultZoom` behavior until they choose a fit mode from the toolbar.
 *
 * @param {DefaultZoomMode | undefined} mode
 * @returns {FitMode}
 */
export function fitModeFromDefaultZoomMode(mode) {
  switch (mode) {
    case 'fit-width':
      return 'width';
    case 'fit-height':
      return 'height';
    case 'fit-page':
      return 'both';
    default:
      return 'none';
  }
}

/**
 * Combine one page or a facing pair into the dimensions that must fit.
 * Widths add across a spread while the tallest sheet determines its height.
 *
 * @param {Array<{ width: number, height: number }>} dimensions
 * @returns {{ width: number, height: number } | null}
 */
export function combineFitDimensions(dimensions) {
  const valid = dimensions.filter(({ width, height }) => width > 0 && height > 0);
  if (!valid.length) return null;

  return {
    width: valid.reduce((total, section) => total + section.width, 0),
    height: Math.max(...valid.map((section) => section.height)),
  };
}

/**
 * Resolve the sheet unit that fit-to-page/width/height should target.
 *
 * - `two_pages`: combine every sheet in the provided unit (one facing pair).
 * - `single_page`: use only the first sheet. Stacked pages share one viewport
 *   unit; summing every sheet width would under-zoom multi-page documents.
 *
 * @param {'single_page' | 'two_pages'} preview
 * @param {Array<{ width: number, height: number }>} dimensions
 * @returns {{ width: number, height: number } | null}
 */
export function resolveFitUnitDimensions(preview, dimensions) {
  if (preview === 'two_pages') {
    return combineFitDimensions(dimensions);
  }

  const first = dimensions.find(({ width, height }) => width > 0 && height > 0);
  return first ? { width: first.width, height: first.height } : null;
}

/**
 * Calculate a clamped percentage zoom from already-measured dimensions.
 * Keeping this DOM-free makes the fit contract testable independently of
 * React, ResizeObserver, and an embedding iframe.
 *
 * @param {{
 *   mode: FitMode,
 *   contentWidth: number,
 *   contentHeight: number,
 *   availableWidth: number,
 *   availableHeight: number,
 *   minZoom: number,
 *   maxZoom: number,
 * }} input
 * @returns {number | null}
 */
export function calculateFitZoom({
  mode,
  contentWidth,
  contentHeight,
  availableWidth,
  availableHeight,
  minZoom,
  maxZoom,
}) {
  if (
    mode === 'none' ||
    contentWidth <= 0 ||
    contentHeight <= 0 ||
    availableWidth <= 0 ||
    availableHeight <= 0
  ) {
    return null;
  }

  const scaleX = (availableWidth / contentWidth) * 100;
  const scaleY = (availableHeight / contentHeight) * 100;
  const zoom = mode === 'width'
    ? scaleX
    : mode === 'height'
      ? scaleY
      : Math.min(scaleX, scaleY);

  return Math.min(Math.max(zoom, minZoom), maxZoom);
}
